method fib4(n: int) returns (result: int)
    requires n >= 0
    ensures result == fib4_value(n)
{
    var f: array<int> := new int[n + 1];
    f[0] := 0;
    if n >= 1 {
        f[1] := 0;
    }
    if n >= 2 {
        f[2] := 2;
    }
    if n >= 3 {
        f[3] := 0;
    }
    var i: int;
    for i := 4 to n
        invariant 0 <= i <= n + 1
        invariant forall j: int :: 0 <= j < i ==> f[j] == fib4_value(j)
    {
        f[i] := f[i - 1] + f[i - 2] + f[i - 3] + f[i - 4];
    }
    result := f[n];
}

