function fib4_value(n: int): int
    requires n >= 0
    decreases n
{
    if n == 0 then 0
    else if n == 1 then 0
    else if n == 2 then 2
    else if n == 3 then 0
    else fib4_value(n - 1) + fib4_value(n - 2) + fib4_value(n - 3) + fib4_value(n - 4)
}
